// <auto-generated/>
using System;
using System.Collections.Generic;
using System.Text;
using System.IO;
using System.Reflection;
using System.Security.Permissions;


namespace Sunplus.Agent.Configurations
{
    internal sealed class ChangedWatcher
    {
        static FileSystemWatcher FileWatcher = null;
        static object FileWatcherLocker = new object();

        static Dictionary<string, IConfiguration> Configurations = new Dictionary<string, IConfiguration>();

        [PermissionSet(SecurityAction.Demand, Name = "FullTrust")]
        public static void Add(IConfiguration configuration, string appPath)
        {
            Configurations.Add((configuration as Configuration).FilePath.ToLower(), configuration);

            // Double checking
            if (FileWatcher == null)
            {
                lock (FileWatcherLocker)
                {
                    if (FileWatcher == null)
                    {
                        // Handle file changed by FileSystemWatcher
                        FileWatcher = new FileSystemWatcher();
                        FileWatcher.Path = appPath;
                        FileWatcher.Filter = "*.ini";
                        FileWatcher.IncludeSubdirectories = false;

                        /* Watch for changes in LastAccess and LastWrite times, and
                           the renaming of files or directories. */
                        FileWatcher.NotifyFilter = NotifyFilters.LastWrite;

                        FileWatcher.Changed += new FileSystemEventHandler(FileWatcher_Changed);

                        // Begin watching.
                        FileWatcher.EnableRaisingEvents = true;
                    }
                }
            }
        }

        static void FileWatcher_Changed(object sender, FileSystemEventArgs e)
        {
            string fullPath = e.FullPath.ToLower();

            IConfiguration configuration = Configurations.ContainsKey(fullPath) ? Configurations[fullPath] : null;

            if (configuration != null)
            {
                configuration.Reload();
            }
        }
    }    
}
